Given an array arr[], the task is to find all possible indices {i, j, k} of triplet {arr[i], arr[j], arr[k]} such that their sum is equal to zero and all indices in a triplet should be distinct (i != j, j != k, k != i). We need to return indices of a triplet in sorted order, i.e., i < j < k.Examples :Input: arr[] = [0, -1, 2, -3, 1]Output: [[0, 1, 4], [2, 3, 4]]Explanation:  Two triplets with sum 0 are:arr[0] + arr[1] + arr[4] = 0 + (-1) + 1 = 0arr[2] + arr[3] + arr[4] = 2 + (-3) + 1 = 0Input: arr[] = [1, -2, 1, 0, 5]Output: [[0, 1, 2]]Explanation: Only triplet which satisfies the condition is arr[0] + arr[1] + arr[2] = 1 + (-2) + 1 = 0Input: arr[] = [2, 3, 1, 0, 5]Output: []Explanation: There is no triplet with sum 0Try It YourselfTable of Content[Naive Approach] Using Three Nested Loops - O(n^3) Time and O(1) Space[Expected Approach] Using Hash Map - O(n^3) Time and O(n) Space[Naive Approach] Using Three Nested Loops - O(n^3) Time and O(1) SpaceThe simplest approach is to generate all possible triplets using three nested loops and if the sum of any triplet is equal to zero then add it to the result. 
            C++

    // C++ program to find triplet having sum zero using
// three nested loops

#include <iostream>
#include <vector>
using namespace std;

vector<vector<int>> findTriplets(vector<int> &arr) {
    vector<vector<int>> res; 
    int n = arr.size(); 

    // Generating all triplets
    for (int i = 0; i < n - 2; i++) {
        for (int j = i + 1; j < n - 1; j++) {
            for (int k = j + 1; k < n; k++) {

                // If the sum of a triplet equals to zero
              	// then add it's indices to the result
                if (arr[i] + arr[j] + arr[k] == 0) 
                    res.push_back({i, j, k});
            }
        }
    }
    return res; 
}

int main() {
    vector<int> arr = {0, -1, 2, -3, 1};
    vector<vector<int>> res = findTriplets(arr);
    for(int i = 0; i < res.size(); i++)
        cout << res[i][0] << " " << res[i][1] << " " << res[i][2] << endl;

    return 0;
}


